/* story.js — saga 5 capitoli x 5 episodi, IT */
(function () {
'use strict';
const CHAPTERS = [
  { n: 1, title: 'La Schiuma che Trema', desc: 'Affitto scaduto. Un chasen consumato. Ricomincia dal rito.' },
  { n: 2, title: 'Zucchero e Sale', desc: 'Ren ritorna come critico. Ogni scelta cambia il gusto del board.' },
  { n: 3, title: 'La Notte Yuzu', desc: 'Blackout a Kyoto. Si serve a lume di candela, col fiato corto.' },
  { n: 4, title: 'Sakura Marcia', desc: 'Yuki sparisce sotto la pioggia. Cercala tazza dopo tazza.' },
  { n: 5, title: "L'Ultima Tazza", desc: "L'Uomo della Pioggia chiede l'ultimo tè. Tre finali ti aspettano." },
  { n: 6, title: 'Il Primo del Resto', desc: 'Dopo l’ultima tazza: lettere in ritardo, duelli di schiuma, un gatto. Quarto finale.' },
  { n: 7, title: 'Neve su Kyoto', desc: 'Inverno. Il tetto perde, il tè gela sul bordo. Si serve caldo e in fretta.' },
  { n: 8, title: 'Festival delle Lanterne', desc: 'Mercato notturno, tè alle lanterne, una sfida che profuma di miele.' },
  { n: 9, title: 'Ritorno al Vapore', desc: 'Disgelo e tempesta. Il locale si ricostruisce tazza dopo tazza. Le più dure.' },
];
/* Personaggi — schede senza spoiler sui finali */
const CHARACTERS = [
  { name: 'Aoi', role: 'tu · erede', desc: 'Ventiseienne ansiosa, mani che tremano e cuore che resta. Ha ereditato il chashitsu Hana e un debito.' },
  { name: 'Hana', role: 'nonna · voce', desc: 'Fondatrice del locale. Morta, ma presente in 25 lettere, nei sogni e nel vapore.' },
  { name: 'Ren', role: 'ex · critico', desc: 'Ex fidanzato tornato come critico gastronomico. Piede che trema quando mente.' },
  { name: 'Yuki', role: 'bambina · disegni', desc: '7 anni, quasi muta dopo un lutto. Disegna solo tazze. Le sue pagine sono mappe.' },
  { name: 'Takeshi', role: 'Uomo della Pioggia', desc: 'Anziano elegante con l’ombrello nero. Primo amore di Hana, 60 anni dopo.' },
  { name: 'Mika', role: 'food-blogger', desc: '40k follower, cuore più grande del telefono. Dalla live acida alla festa degli addii.' },
  { name: 'Sōma', role: 'postino · lettere', desc: '62 anni, vedovo. Consegna anche lettere mai spedite. Una per Hana pesa 30 anni.' },
  { name: 'Kiku', role: 'rivale · 81 anni', desc: 'Chashitsu dall’altra parte del fiume. Finge astio, manda candele e clienti quando piove.' },
  { name: 'Itsuki', role: 'fratello di Ren', desc: '24 anni, fotografo di notte. Un amore non ricambiato per Aoi, un rullino da 36 foto.' },
  { name: 'Rei', role: 'madre di Yuki', desc: 'Infermiera in turno doppio, senso di colpa negli occhi. Sta imparando a esserci.' },
  { name: 'Tè', role: 'gatto del tempio', desc: 'Randagio che dorme sulle tazze calde. Rivale di Mugi. Porta fortuna se coccolato.' },
  { name: 'Mugi', role: 'tuo chasen 🐾', desc: 'Frullino-cucciolo: Germoglio → Bamboo → Lacca oro. Non muore mai, al massimo dorme.' },
];
const T = (t, c, m, mini, bias = -1, mech = null, quota = 0) => ({ moves: m, targetTile: t, targetCount: c, biasTile: bias, mini, mechanic: mech, quota });
const STORY = [
/* CAP 1 */
{id:1,chap:1,ep:1,kicker:'Cap.1-1 · Il debito',title:'Il locale che respira piano',text:`Kyoto, 5:47. La saracinesca del chashitsu Hana cigola come un ginocchio vecchio.\n\nSul bancone trovi la busta dell'affitto — 30 giorni — e sotto, una lettera di nonna Hana: "Aoi, la schiuma trema solo se hai paura. Frulla come se abbracciassi qualcuno."\n\nIl primo cliente è il postino: ordina un usucha veloce. Le tue mani sudano. Il chasen pesa il doppio.`,cliff:`Fuori, uno sconosciuto con l'ombrello nero ti fissa senza ordinare. Il postino Sōma esita sulla soglia con una busta ingiallita: "Questa… forse un altro giorno." Dietro di lui, un ragazzo con la stessa divisa troppo grande — suo nipote, primo giorno di prova — inciampa sullo zerbino: "Nonno, un giorno farò meglio di te."`,choiceA:{label:'«Ho paura, ma apro lo stesso.»',effect:'coraggio'},choiceB:{label:'«Nonna, guidami le mani.»',effect:'dolcezza'},level:T(0,12,26,'awa'),letter:`Lettera 1 — "Il primo tè è sempre amaro. Servilo lo stesso. H."`,ps:{coraggio:`H. Hai aperto con la paura addosso. Sōma l'ha visto: ha fatto un passo indietro, poi è tornato.`,
       dolcezza:`H. Hai detto: guidami le mani. Ti ho risposto dal vapore. Ero ancora lì, per quello.`},},
{id:2,chap:1,ep:2,kicker:'Cap.1-2 · Il rito',title:'Cerchi, non fretta',text:`Hana diceva: il chasen va mosso a "M", ma il cuore va mosso a cerchi.\n\nYuki, 7 anni, entra scalza e ti guarda senza parlare. Disegna una tazza storta sul quaderno. Indica la tua mano: vuole vedere la schiuma.\n\nSe frulli troppo forte, amaro. Troppo piano, acqua verde.`,cliff:`Yuki sorride per la prima volta. Poi indica la porta: l'uomo con l'ombrello è ancora lì.`,choiceA:{label:'Frulli piano per Yuki',effect:'dolcezza'},choiceB:{label:'Frulli forte per fare in fretta',effect:'rabbia'},level:T(0,14,26,'awa'),letter:`Lettera 2 — "Chi entra scalzo, porta verità. Offrigli un mochi."`,ps:{dolcezza:`H. Quella bambina scalza ti ha fatto frullare piano per la prima volta. Non guardava la tazza: guardava te.`,
       rabbia:`H. Hai frullato forte per finire. Lei ha smesso di sorridere. Una tazza si rimette: un sorriso, no.`},},
{id:3,chap:1,ep:3,kicker:'Cap.1-3 · Il primo giudizio',title:'La food-blogger',text:`Arriva Mika, 40k follower, telefono già in live: "Vediamo se questo posto merita o chiude."\n\nVuole una sakura latte fotogenica. Il rosa deve essere perfetto o nei commenti ti massacrano.\n\nLe mani tremano più del vapore. Respiri: 4-7-8 come ti ha insegnato Hana nelle notti d'ansia.`,cliff:`La live si blocca a 39k spettatori. Mika assaggia. Silenzio. Poi legge un commento: "Kiku_del_fiume: schiuma acerba. Venga a imparare da me, la nipote di Hana." In un angolo della live si vede una zampa tigrata: "È Moka, la mia gatta. Giudice suprema della schiuma," aggiunge Kiku_del_fiume.`,choiceA:{label:'Respiri e versi con calma',effect:'coraggio'},choiceB:{label:'Versi di fretta per finire la live',effect:'rabbia'},level:T(2,14,25,'latte'),letter:`Lettera 3 — "La bellezza senza calma è solo trucco."`,ps:{coraggio:`H. Quella volta hai aspettato il silenzio prima di versare. I 39mila non l'hanno notato. Io sì.`,
        rabbia:`H. Quella volta hai versato in fretta per chiudere la live. È andata bene. Ma non è la stessa cosa.`},},
{id:4,chap:1,ep:4,kicker:'Cap.1-4 · Il sapore acido',title:'Yuzu per il pianto',text:`Un ragazzo col maglione bucato piange al tavolo 3. Ha perso il lavoro. Chiede "qualcosa di acido, che mi svegli".\n\nGli prepari uno yuzu matcha. L'acidità taglia la tristezza come un coltello caldo nel burro.\n\nLui ride a metà sorso. Piangere e ridere insieme: è il gusto esatto dell'usucha quando manca qualcuno.`,cliff:`Sul vetro, qualcuno ha scritto col dito: TORNA DOMANI. Non sai chi.`,choiceA:{label:'Offri il tè gratis',effect:'dolcezza'},choiceB:{label:'Fai pagare, servono soldi',effect:'coraggio'},level:T(3,15,25,'respiro'),letter:`Lettera 4 — "Il tè gratis torna indietro centuplicato. Fidati."`,ps:{dolcezza:`H. Hai offerto lo yuzu gratis. Ha smesso di piangere a metà sorso, e ha finito la tazza da solo.`,
       coraggio:`H. Quella sera ti mancavano i soldi e li hai chiesti. È il gesto più onesto del tuo primo anno.`},},
{id:5,chap:1,ep:5,kicker:'Cap.1-5 · Soglia',title:'Venti tazze per restare',text:`Ultimo giorno della settimana. Ti mancano 20 usucha per pagare metà affitto.\n\nIl locale si riempie all'improvviso: pioggia fuori, tutti dentro. Il vapore appanna i vetri. Senti Hana ridere nel rumore del frullino.\n\nQuesta non è una prova. È una promessa.`,cliff:`A chiusura, Ren — il tuo ex — entra. "Devo recensirti. Perdonami."`,choiceA:{label:'«Entra. Ma ti giudicherò io.»',effect:'rabbia'},choiceB:{label:'«Una tazza. Solo una.»',effect:'dolcezza'},level:T(0,16,26,'awa'),letter:`Lettera 5 — "Se è tornato, non è per il tè. Preparati."`,ps:{rabbia:`H. L'hai fatto entrare per giudicarlo. Lui ha accettato. Alla seconda tazza non guardavi il taccuino.`,
       dolcezza:`H. Gli hai dato una tazza sola, come si dà a chi ha freddo. Non gli hai chiesto niente.`},},
/* CAP 2 */
{id:6,chap:2,ep:1,kicker:'Cap.2-1 · Il critico',title:'Ren assaggia',text:`Ren ha il taccuino nuovo e le stesse mani di quando avevate 19 anni.\n\nOrdina koicha, il più denso, il più difficile. "Sono qui come critico, Aoi. Niente sconti."\n\nMa sotto il tavolo, il suo piede trema. Lo conosci quel tremito: mente.`,cliff:`Scrive qualcosa e lo copre con la mano. Vedi solo: "Il sapore di quando—"`,choiceA:{label:'«Dimmi la verità, non la recensione.»',effect:'dolcezza'},choiceB:{label:'«Giudica pure. Non ho paura.»',effect:'rabbia'},level:T(1,15,25,'latte',4),letter:`Lettera 6 — "L'amore vecchio è come il koicha: amaro se lo lasci freddare."`,ps:{dolcezza:`H. Gli hai chiesto la verità, non la recensione. Il suo piede ha smesso di tremare. Ha risposto.`,
       rabbia:`H. Gli hai detto: giudica pure. Lui ha giudicato per bene. La paura, quella sera, era la tua.`},},
{id:7,chap:2,ep:2,kicker:'Cap.2-2 · Sale',title:'La recensione a metà',text:`La bozza di Ren trapelata online: "Chashitsu Hana: commovente ma acerbo. 6.5."\n\nAcerbo. La parola ti trafigge più di un addio. I clienti calano. Yuki smette di disegnare tazze intere: le fa a metà.\n\nQuella notte non dormi. Frulli acqua e sale per rabbia.`,cliff:`Alle 3am bussano. È Ren, fradicio. "Cancellala. Riscriviamola insieme."`,choiceA:{label:'Lo lasci entrare fradicio',effect:'dolcezza'},choiceB:{label:'«Prima dimmi perché sei andato via.»',effect:'coraggio'},level:T(4,15,25,'respiro',4),letter:`Lettera 7 — "Il sale nel tè è un errore. Nel cuore, una medicina."`,ps:{coraggio:`H. Quella notte gli hai chiesto perché se n'era andato. Hai aspettato la risposta. Lui l'ha detta.`,
        dolcezza:`H. Quella notte l'hai fatto entrare bagnato, senza chiedere niente. È stato quello il gesto giusto.`},},
{id:8,chap:2,ep:3,kicker:'Cap.2-3 · Zucchero',title:'Una tazza, solo una',text:`Pioggia sui vetri. Ren chiede "l'usucha di Hana".\n\nLe tue mani tremano. Se scegli la rabbia, il vassoio si riempirà di ombre nere. Se scegli la dolcezza, fioriranno sakura.\n\nL'Uomo della Pioggia dal fondo sussurra: "Attenta. Lui non beve mai fino in fondo."`,cliff:`Ren alza la tazza. Le vostre dita si sfiorano sul bordo caldo.`,choiceA:{label:'«Sei qui per chiudere il locale?» (rabbia)',effect:'rabbia'},choiceB:{label:'«Resta per una tazza.» (dolcezza)',effect:'dolcezza'},level:T(0,16,26,'awa',-1),letter:`Lettera 8 — "Chi non finisce il tè, non ha finito di amare."`,ps:{rabbia:`H. Gli hai chiesto se era venuto per chiudere il locale. Ha abbassato gli occhi, ma ha finito la tazza.`,
       dolcezza:`H. Gli hai detto: resta per una tazza. Le vostre dita si sono sfiorate sul bordo caldo.`},},
{id:9,chap:2,ep:4,kicker:'Cap.2-4 · Confessione',title:'Perché partì',text:`Ren confessa: cinque anni fa accettò un lavoro a Osaka per pagarti la scuola del tè. Non te lo disse per orgoglio. Poi la vergogna divenne distanza.\n\n"Ti ho persa cercando di salvarti."\n\nIl koicha sul fuoco rischia di bruciare. Come voi, se non lo togliete in tempo.`,cliff:`Yuki porge a Ren un disegno: voi due dentro una tazza gigante. Sulla porta, un ragazzo con una macchina fotografica — Itsuki, il fratello di Ren — scatta di nascosto e arrossisce.`,choiceA:{label:'Perdoni a metà (tieni distanza)',effect:'coraggio'},choiceB:{label:'Perdoni davvero (mani unite)',effect:'dolcezza'},level:T(2,16,26,'latte'),letter:`Lettera 9 — "Perdonare è versare due volte dalla stessa teiera."`,ps:{coraggio:`H. Hai perdonato a metà, restando a distanza. È durato sei mesi. Poi lui ha smesso di tornare.`,
       dolcezza:`H. Gli hai preso le mani. Non ha pianto: ha bevuto il koicha con gli occhi lucidi.`},},
{id:10,chap:2,ep:5,kicker:'Cap.2-5 · Verdetto',title:'La seconda recensione',text:`Ren pubblica: "Chashitsu Hana: 9. Il gusto di chi resta. Tornerò ogni pioggia."\n\nIl locale esplode. Ma il proprietario del muro alza l'affitto. Gioia e ansia insieme, come schiuma e amaro.\n\nQuella sera Ren lava le tazze con te. In silenzio. Che è il modo più rumoroso di amarsi.`,cliff:`Blackout in tutta Kyoto. Solo il tuo locale ha candele accese.`,choiceA:{label:'Accendi candele per tutti',effect:'dolcezza'},choiceB:{label:'Chiudi e goditi Ren',effect:'rabbia'},level:T(5,17,26,'respiro'),letter:`Lettera 10 — "La luce attira falene e miracoli. Accendila."`,ps:{dolcezza:`H. Hai acceso le candele per tutti, anche per chi non poteva pagare. Al blackout erano ancora accese.`,
       rabbia:`H. Hai chiuso e vi siete presi il resto della notte. L'indomani ti sei alzata presto: il tetto era da rifare.`},},
/* CAP 3 */
{id:11,chap:3,ep:1,kicker:'Cap.3-1 · Buio',title:'La notte yuzu',text:`Blackout. Kyoto è un mare nero. Nel tuo locale, dieci candele e dieci sconosciuti bloccati dalla pioggia.\n\nUna signora anziana trema: attacchi di panico al buio. Le prepari uno yuzu caldo e le insegni a respirare con te: 4 in, 7 trattieni, 8 fuori.\n\nTutto il locale respira insieme. Il buio diventa coperta.`,cliff:`Un colpo alla porta. Nessuno fuori. Solo un ombrello nero appoggiato al muro.`,choiceA:{label:'Guidi il respiro di tutti',effect:'coraggio'},choiceB:{label:'Servi prima, parli dopo',effect:'dolcezza'},level:T(3,16,25,'respiro'),letter:`Lettera 11 — "Al buio, il tè si sente di più. Come le persone."`,ps:{coraggio:`H. Quella notte hai guidato il respiro di dieci sconosciuti. Una signora ha contato con te: quattro, sette.`,
       dolcezza:`H. Hai servito lo yuzu prima di parlare, e il buio si è riempito di tazze. Non chiedeva niente nessuno.`},},
{id:12,chap:3,ep:2,kicker:'Cap.3-2 · Sussurri',title:'L’ombrello nero',text:`L'ombrello è dell'Uomo della Pioggia. Dentro c'è un biglietto: "Servimi quando smette di piovere. Sarà l'ultima."\n\nChi è? Il proprietario del muro impallidisce quando lo nomini. Ren impallidisce quando lo descrivi.\n\nYuki invece lo disegna sorridente. I bambini vedono ciò che gli adulti rimuovono.`,cliff:`La luce torna per un secondo. Specchiato nel vetro: Hana giovane che ti guarda.`,choiceA:{label:'Chiedi a Yuki chi è',effect:'dolcezza'},choiceB:{label:'Affronti il proprietario',effect:'coraggio'},level:T(4,15,25,'awa',4),letter:`Lettera 12 — "Quando piove troppo, qualcuno deve chiedere l'ultimo tè. Ascoltalo."`,ps:{dolcezza:`H. Hai chiesto a Yuki chi era. Ha risposto con un disegno: una tazza e un sole, e basta.`,
       coraggio:`H. Hai affrontato il proprietario. Quella sera è diventato grigio. Poi ha accettato di aspettare il giovedì.`},},
{id:13,chap:3,ep:3,kicker:'Cap.3-3 · Febbre',title:'Aoi si ammala',text:`Lavori 16 ore al freddo. Febbre a 39. Ma ci sono clienti fuori.\n\nRen vuole chiudere. Tu vuoi aprire. Litigate per amore, che è il peggior motivo per litigare.\n\nHana in sogno: "Il tè aspetta. La salute no. Chiudi un giorno, stupida bambina mia."`,cliff:`Ti svegli. Ren dorme sulla sedia accanto, mano sulla tua fronte.`,choiceA:{label:'Chiudi un giorno (ti curi)',effect:'dolcezza'},choiceB:{label:'Apri febbricitante',effect:'rabbia'},level:T(1,16,26,'latte'),letter:`Lettera 13 — "Riposare è servire il tè a te stessa."`,ps:{dolcezza:`H. Hai chiuso un giorno e ti sei curata. Lui ha badato a te, e male: pessimo infermiere, ottimo cuscino.`,
       rabbia:`H. Hai aperto febbricitante, perché c'era la fila. Poi sei crollata sul tatami: ha imparato il locale da sé.`},},
{id:14,chap:3,ep:4,kicker:'Cap.3-4 · Candela',title:'Cena a lume',text:`Con la febbre scesa, organizzi una cena segreta a lume di candela: solo 8 posti, solo koicha denso e storie vere.\n\nOgni cliente racconta una perdita. Tu racconti Hana. Ren racconta Osaka e la vergogna.\n\nPianto collettivo nel vapore. Nessuno fotografa. Miracolo.`,cliff:`L'Uomo della Pioggia prenota l'ottavo posto. "Quasi smette di piovere."`,choiceA:{label:'Lo accogli senza domande',effect:'coraggio'},choiceB:{label:'Gli chiedi il nome',effect:'dolcezza'},level:T(1,17,26,'respiro'),letter:`Lettera 14 — "Otto posti, otto lutti, un'unica teiera."`,ps:{coraggio:`H. Lo hai accolto senza domande. Ha bevuto il koicha in silenzio, e quella sera siamo stati in nove.`,
       dolcezza:`H. Gli hai chiesto il nome. Ha risposto piano, come chi lo ripete dopo trent'anni senza usarlo.`},},
{id:15,chap:3,ep:5,kicker:'Cap.3-5 · Schiarita',title:'Quasi sereno',text:`La pioggia rallenta dopo 11 giorni. Il locale profuma di yuzu e cera.\n\nRen ti porge una chiave: ha affittato il magazzino sopra per farne una sala tatami. "Restiamo. Costruiamo."\n\nMa il telefono squilla: Yuki non è tornata a casa da scuola.`,cliff:`Il suo quaderno trovato sotto la pioggia: ultima pagina, una tazza nera.`,choiceA:{label:'Corri a cercarla subito',effect:'coraggio'},choiceB:{label:'Chiami prima sua madre',effect:'dolcezza'},level:T(3,18,27,'awa'),letter:`Lettera 15 — "Quando un bambino disegna nero, corri. Non pensare."`,ps:{coraggio:`H. Sei corsa a cercarla. Ti sei presa la pioggia addosso, e lei è tornata con te, almeno quella sera.`,
       dolcezza:`H. Hai chiamato prima sua madre. Scelta lenta, e per questo esatta: è così che una bambina torna a casa.`},},
/* CAP 4 */
{id:16,chap:4,ep:1,kicker:'Cap.4-1 · Scomparsa',title:'Sakura marcia',text:`Yuki è sparita da 6 ore. Pioggia di nuovo forte. La polizia dice "aspettiamo".\n\nTu non aspetti. Prendi torcia, tè caldo in thermos e i suoi disegni come mappa: ogni tazza disegnata è un luogo reale — il ponte, il tempio, il distributore rosa.\n\nRen corre con te. L'amore si misura in pozzanghere attraversate.`,cliff:`Al ponte: il suo nastro rosa impigliato. Sotto, passi piccoli verso il fiume.`,choiceA:{label:'Segui i passi da sola',effect:'coraggio'},choiceB:{label:'Chiami Ren e restate uniti',effect:'dolcezza'},level:T(2,17,26,'latte',4),letter:`Lettera 16 — "I nastri rosa non mentono. Seguili."`,ps:{coraggio:`H. Hai seguito quei passi da sola, con la torcia in mano. Sotto il ponte tremava tutto tranne la torcia.`,
       dolcezza:`H. Hai chiamato Ren e siete andati uniti. Lui l'ombrello, tu il thermos: due metà per una bambina.`},},
{id:17,chap:4,ep:2,kicker:'Cap.4-2 · Fiume',title:'Il thermos caldo',text:`La trovi sotto il ponte, abbracciata al quaderno, infreddolita. Non parla, ma beve lo yuzu tutto d'un fiato.\n\n"Disegnavo il fiume," sussurra. Prime parole in mesi. "Volevo vedere dove va la tristezza."\n\nPiangi più lei. Ren vi copre col suo cappotto. Tre cuori sotto una stoffa.`,cliff:`Nel quaderno, pagina nuova: voi tre dentro una tazza, stavolta intera.`,choiceA:{label:'La stringi senza parlare',effect:'dolcezza'},choiceB:{label:'Le prometti che non scappa più la tristezza',effect:'coraggio'},level:T(5,17,26,'respiro'),letter:`Lettera 17 — "La tristezza va come il fiume: bevila calda e lasciala andare."`,ps:{dolcezza:`H. L'hai stretta senza parlare. Ha smesso di tremare al terzo minuto. Meglio così che con le parole.`,
       coraggio:`H. Le hai promesso che la tristezza non scappa più. Non è vero. Ma quella sera, per lei, lo era.`},},
{id:18,chap:4,ep:3,kicker:'Cap.4-3 · Madre',title:'La madre di Yuki',text:`Sua madre arriva trafelata, infermiera in turno doppio, senso di colpa negli occhi.\n\n"Non ci sono mai." Le servi un koicha doppio e le dici: "Ci sei adesso."\n\nLei crolla. Racconta notti in ospedale e Yuki sola coi disegni. Capisci Hana: servire è anche assolvere.`,cliff:`Rei, la madre di Yuki, ti porge una busta: soldi per l'affitto. "Hana fece lo stesso per me." Poi sussurra: "Sto pensando di chiedere il part-time. Yuki merita una madre sveglia."`,choiceA:{label:'Accetti (per restare aperti)',effect:'coraggio'},choiceB:{label:'Rifiuti (orgoglio)',effect:'rabbia'},level:T(1,18,27,'awa'),letter:`Lettera 18 — "Accettare aiuto è il tè più difficile da versare."`,ps:{coraggio:`H. Hai preso i soldi. Ti ho sentito lottare dietro la porta, e poi hai aperto: bene.`,
        rabbia:`H. Hai rifiutato per orgoglio. Non ti rimprovero: è la stessa cosa che feci io con l'affitto del 71.`},},
{id:19,chap:4,ep:4,kicker:'Cap.4-4 · Festa',title:'Matsuri delle tazze',text:`Per festeggiare il ritorno di Yuki, organizzi un mini-matsuri: tutti portano la propria tazza da casa.\n\nC'è la tazza sbeccata del postino, quella arcobaleno di Mika, quella nera dell'Uomo della Pioggia — venuto davvero.\n\nYuki ride e disegna a raffica. Il locale è pieno di vapore e futuro.`,cliff:`L'Uomo si alza: "Ha smesso di piovere. Domani, l'ultimo tè." Sōma lascia sul bancone una cartolina del nipote: "Primo giro da solo. Non ho perso niente!"`,choiceA:{label:'Gioisci con tutti',effect:'dolcezza'},choiceB:{label:'Tremi: sai cosa significa',effect:'coraggio'},level:T(0,19,27,'latte'),letter:`Lettera 19 — "Festeggia prima del temporale. È quello il coraggio."`,ps:{dolcezza:`H. Hai gioito con tutti, anche se sapevi. Soprattutto quella: la gioia vera è sapere e restare lì.`,
       coraggio:`H. Quella sera tremavi. Sōma ti ha messo davanti la cartolina del nipote, e ha finito il suo giro.`},},
{id:20,chap:4,ep:5,kicker:'Cap.4-5 · Vigilia',title:'Notte prima dell’ultimo',text:`Non dormi. Rileggi tutte le 19 lettere. Capisci: Hana conosceva l'Uomo della Pioggia. Era il suo primo amore, partito in guerra e mai tornato — o forse tornato come pioggia.\n\nRen ti trova tra le lettere: "Qualunque cosa chieda domani, la affrontiamo insieme."\n\nVi addormentate sul tatami tra tazze vuote. L'alba sa di matcha e sale.`,cliff:`Bussano all'alba. Silenzio totale. Solo profumo di pioggia vecchia. E un sogno vivido: Hana a vent'anni che ride con un ragazzo sotto un ombrello di carta.`,choiceA:{label:'Apri mano nella mano con Ren',effect:'dolcezza'},choiceB:{label:'Apri da sola, da erede',effect:'coraggio'},level:T(4,18,27,'respiro',-1),letter:`Lettera 20 — "L'ultimo tè non è una fine. È un esame di tenerezza."`,ps:{dolcezza:`H. Hai aperto con Ren, mano nella mano. Non ti sei fatta coraggio da sola, e va bene così: era in due.`,
       coraggio:`H. Hai aperto da sola, da erede. In quel momento l'ho capito: non ti avevo lasciato niente, insegnato.`},},
/* CAP 5 */
{id:21,chap:5,ep:1,kicker:'Cap.5-1 · Lui',title:'L’Uomo della Pioggia',text:`È anziano, elegante, occhi color tè freddo. "Sono Takeshi. Hana mi promise l'ultimo tè 60 anni fa. Poi la vita ci versò altrove."\n\nChiede esattamente il koicha di allora: denso, amaro, con due mochi.\n\nMentre frulli, le mani non tremano più. Sono mani di qualcun'altra: di Hana giovane.`,cliff:`Beve un sorso. Piange senza nascondersi. "È lei. È ancora lei."`,choiceA:{label:'Servi in silenzio',effect:'dolcezza'},choiceB:{label:'Chiedi la loro storia',effect:'coraggio'},level:T(1,18,27,'awa'),letter:`Lettera 21 — "Se viene Takeshi, dagli il mio chasen. È suo."`,ps:{dolcezza:`H. Quella sera hai servito in silenzio. Lui ha capito da solo: si riconosce una mano dal modo in cui tace.`,
       coraggio:`H. Gli hai chiesto la loro storia. Ha parlato un'ora senza guardare l'ora: sessant'anni, nessun minuto perso.`},},
{id:22,chap:5,ep:2,kicker:'Cap.5-2 · Lettere bruciate',title:'60 anni in una tazza',text:`Takeshi racconta: lui e Hana si amavano. Lui partì, lei sposò un altro per salvare il locale. Si scrissero 40 anni senza mai rivedersi.\n\nTi porge un pacco di lettere: "Bruciale con me. O pubblicale. Decidi tu cosa meritano gli amori interrotti."\n\nRen ti guarda. Capite entrambi: questa è anche la vostra prova.`,cliff:`Yuki disegna Hana giovane e Takeshi giovane dentro la stessa tazza.`,choiceA:{label:'Bruciate (restano vostre)',effect:'rabbia'},choiceB:{label:'Leggetele al locale (diventano di tutti)',effect:'dolcezza'},level:T(2,19,28,'latte'),letter:`Lettera 22 — "L'amore segreto scalda una persona. L'amore detto scalda un paese."`,ps:{rabbia:`H. Le avete bruciate, e sono restate vostre. Sotto la cenere c'erano anni che nessuno dei due aveva contato.`,
       dolcezza:`H. Le avete lette al locale, a voce alta, con la porta aperta. Da allora qualcuno bussa: le sento da fuori.`},},
{id:23,chap:5,ep:3,kicker:'Cap.5-3 · Scelta tua',title:'Restare o andare',text:`Il proprietario offre: vendi il locale per una cifra enorme, o firma 10 anni di affitto doppio.\n\nRen ha un'offerta a Tokyo. Yuki ti chiede di non chiudere mai. Takeshi ti guarda come Hana ti guardava: "Scegli col ventre, non col menù."\n\nL'ansia ti schiaccia il petto. Respiri 4-7-8. Il chasen nel palmo sembra un cuore.`,cliff:`Devi rispondere entro domani. Il tè di stasera deciderà il sapore della risposta.`,choiceA:{label:'Inclini per Tokyo con Ren',effect:'rabbia'},choiceB:{label:'Inclini per restare a Kyoto',effect:'coraggio'},level:T(3,19,28,'respiro'),letter:`Lettera 23 — "Non esiste scelta giusta. Solo tè versato con onestà."`,ps:{rabbia:`H. Quella sera hai detto: Tokyo. Il tè dopo è uscito amaro, ma l'hai bevuto tutto: anche l'amaro si finisce.`,
       coraggio:`H. Quella sera hai detto: resto, a Kyoto. Ti è costato metà notte e tre vetri. Il vapore sapeva di scelta.`},},
{id:24,chap:5,ep:4,kicker:'Cap.5-4 · Penultima',title:'La festa degli addii possibili',text:`Organizzi una sera dove ognuno porta un addio: Mika lascia la fast-fashion, la madre di Yuki lascia i turni doppi, Ren lascia l'orgoglio.\n\nTu porti la paura di chiudere. La metti in una tazza e la bevi davanti a tutti. Amara. Poi dolce in fondo.\n\nTakeshi si alza: "Domani non chiederò l'ultimo tè. Chiederò il primo del resto."`,cliff:`Tutti piangono ridendo. Yuki ti porge una tazza bianca vuota: "Riempila domani."`,choiceA:{label:'Prometti di riempirla',effect:'dolcezza'},choiceB:{label:'Dici "vedremo domani"',effect:'coraggio'},level:T(5,20,28,'awa'),letter:`Lettera 24 — "La penultima tazza è sempre la più coraggiosa."`,ps:{coraggio:`H. Hai detto «vedremo domani». È la risposta più onesta che ci sia. Non ti chiedo altro.`,
        dolcezza:`H. Hai promesso di riempirla. Ti credo. E se non ci riuscirai domani, quella tazza aspetta comunque.`},},
{id:25,chap:5,ep:5,kicker:'Cap.5-5 · Finale',title:'Matcha eterno',text:`Alba. Takeshi, Ren, Yuki, sua madre, Mika, il postino: tutti seduti.\n\nPreparai sei tazze diverse, una per ciascuno, e una settima vuota per Hana. Il vapore sale dritto, come se qualcuno dal cielo stesse aspirando.\n\nTakeshi beve fino in fondo. Sorride. "Finito. E per questo, infinito."\n\nOra tocca a te: cosa fai del locale, di Ren, di te stessa?`,cliff:`Il chasen smette di tremare tra le tue dita. Il cuore no.`,choiceA:{label:'RESTO — firmo 10 anni, apro sala tatami con Ren',effect:'finale-resta'},choiceB:{label:'LASCIO ANDARE — vendo, viaggio, il tè viaggia con me',effect:'finale-lascia'},level:T(0,21,28,'latte'),letter:`Lettera 25 — "Qualunque tazza sceglierai, io sarò nel vapore. Hana."`},
/* CAP 6 — Il Primo del Resto */
{id:26,chap:6,ep:1,kicker:'Cap.6-1 · La busta',title:'Trent’anni di francobollo',text:`Qualunque finale tu abbia scelto, una mattina Sōma torna. Stessa busta ingiallita, mani che tremano più delle tue il primo giorno.\n\n"È per Hana. Del 1994. Non l'ho mai consegnata: litigai con mio padre postino quel giorno, e poi… vergogna sopra vergogna."\n\nLa apri con lui. Dentro, poche righe di un ammiratore anonimo del suo tè — che scopri essere il padre di Rei. Il cerchio si chiude in un punto che non avevi mai guardato.`,cliff:`Sōma piange ridendo: "Consegna completata. Trent'anni di ritardo, zero di amore in meno." Poi si illumina: "E mio nipote ha fatto il primo giro da solo. Non ha perso niente. Come me… quasi."`,choiceA:{label:'Bruci la busta col tè (rito di chiusura)',effect:'dolcezza'},choiceB:{label:'La incornici nel locale',effect:'coraggio'},level:T(0,17,27,'awa'),letter:`Lettera 26 — "Le lettere in ritardo sono tè freddi: si scaldano col cuore. H."`,ps:{dolcezza:`H. Hai bruciato la busta col tè, e Sōma ha fatto il rito con te. Una consegna, non un addio. Poi il rubinetto.`,
       coraggio:`H. Hai incorniciato la busta vicino alla prima recensione di Ren. Trenta anni di attesa, e un muro solo.`},},
{id:27,chap:6,ep:2,kicker:'Cap.6-2 · Duello',title:'Kiku del fiume',text:`Attraversi il ponte con Mugi e una sfida scritta a mano: Kiku, 81 anni, schiena dritta come un chasen nuovo, ti aspetta nel suo chashitsu speculare.\n\n"Vediamo se la nipote di Hana sa frullare o solo piangere." Duello di schiuma: tre tazze a testa, Yuki giudice con palette da 1 a 10.\n\nA metà gara Kiku sussurra: "Tua nonna barava: cantava mentre frullava. Canta anche tu."`,cliff:`Pareggio. Kiku sbuffa, poi ti abbraccia forte: "Come lei. Testarda e dolce." Dalla cesta spunta Moka, la gatta tigrata, che annusa la tua schiuma e fa le fusa. Verdetto definitivo.`,choiceA:{label:'Canti mentre frulli (come Hana)',effect:'dolcezza'},choiceB:{label:'Frulli in silenzio concentrata',effect:'coraggio'},level:T(2,18,27,'awa',2),letter:`Lettera rivale — Kiku: "La schiuma non mente. Tu non mentire mai alla schiuma."`,ps:{dolcezza:`H. Hai cantato mentre frullavi. Kiku ha smesso di battere le nocche al tavolo: è il suo modo di dire bene.`,
       coraggio:`H. Hai frullato in silenzio e concentrata. La schiuma è salita tonda: Kiku ha capito che stavi ascoltando.`},},
{id:28,chap:6,ep:3,kicker:'Cap.6-3 · Rullino',title:'Trentasei foto',text:`Itsuki parte per Nara all'alba. Ti lascia un rullino da 36 foto e un biglietto: "Sviluppale tu. Io non ho il coraggio di guardare cosa ho amato."\n\nLe sviluppi nel retrobottega con Ren. Foto 1-35: il locale, Yuki, la pioggia, tu di spalle che ridi. Foto 36: Hana giovane che ride — scattata a una vecchia stampa, il suo modo di dirti che ha capito tutto.\n\nRen stringe la spalla del fratello alla stazione. Nessuno dice "ti amo". Tutti lo dicono.`,cliff:`Il treno parte. Itsuki dal finestrino alza la macchina fotografica un'ultima volta.`,choiceA:{label:'Gli prometti una tazza a Nara',effect:'dolcezza'},choiceB:{label:'Lo saluti senza promesse',effect:'coraggio'},level:T(2,18,28,'latte'),letter:`Foto 36 — sul retro, grafia di Itsuki: "L'amore fotografato resta. Quello vissuto vola."`,ps:{dolcezza:`H. Gli hai promesso una tazza a Nara. Ha alzato la macchina dal finestrino: le promesse si onorano in ritardo.`,
       coraggio:`H. Lo hai salutato senza promesse. Ti è costato metà pomeriggio. Alcune partenze sono giuste così.`},},
{id:29,chap:6,ep:4,kicker:'Cap.6-4 · Il gatto',title:'Tè sceglie la tazza',text:`Un gatto randagio color tè entra dal tempio, annusa tutte le tazze e dorme su quella di Mochi — la tua preferita.\n\nYuki lo battezza "Tè". Mugi è gelosissimo: fa le fusa più forte del solito per riconquistarti.\n\nQuella sera fai il rito più importante: due coccole, una per uno. Il gatto resta. I clienti portano crocchette. Il locale ha ufficialmente due cuccioli.`,cliff:`Tè apre un occhio, ti guarda, e torna a dormire. Fiducia totale. Dal muretto del tempio, una gatta tigrata — Moka, quella di Kiku — li studia. Domani, forse, un’alleanza felina.`,choiceA:{label:'Doppia coccola (Mugi + Tè)',effect:'dolcezza'},choiceB:{label:'Lasci che scelgano loro',effect:'coraggio'},level:T(5,17,27,'respiro'),letter:`Biglietto di Yuki — disegno: un gatto dentro una tazza con scritto "miaou-cha".`,ps:{dolcezza:`H. Hai fatto la doppia coccola. I due gatti hanno preso il bancone: non è un ripiego, è diplomazia.`,
       coraggio:`H. Hai lasciato che scelgano loro: hanno scelto la stessa tazza. Era anche il loro locale, non solo il tuo.`},},
{id:30,chap:6,ep:5,kicker:'Cap.6-5 · Radici',title:'Hana a vent’anni',text:`Ultima notte di luna piena. Prepari il koicha della ricetta originale del 1964, quella di Hana ventenne e Takeshi ragazzo sotto l'ombrello di carta.\n\nMentre frulli, il vapore disegna la scena: ridi, piangi, servi. Sei Hana. Sei Aoi. Sei tutte le donne che hanno tenuto in mano questo chasen.\n\nTakeshi beve l'ultimo sorso e ti porge l'ombrello di carta: "Tienilo. La pioggia continua, ma ora hai il tetto e le ali."`,cliff:`Alba rosa. Mugi dorato al sole. Tè dorme. Yuki disegna. Ren conta le tazze. Tutto è al suo posto, in movimento.`,choiceA:{label:'RADICI E ALI — sala tatami + banchetto itinerante',effect:'finale-radici'},choiceB:{label:'RADICI E ALI — lo stesso, ma prima un viaggio da sola',effect:'finale-radici-sola'},level:T(0,20,28,'latte'),letter:`Lettera 27 — Hana giovane: "Radici per restare, ali per tornare. Prendi tutto."`},
/* CAP 7 — Neve su Kyoto */
{id:31,chap:7,ep:1,kicker:'Cap.7-1 · Prima neve',title:'Il tetto che perde',text:`Dicembre. La prima neve copre Kyoto e il tetto del chashitsu perde proprio sopra il tavolo 3. Sposti il tavolo, metti un secchio, ci infili dentro un rametto di pino: "installazione", dice Yuki seria.\n\nSōma junior arriva trafelato nella tormenta con la posta: "Non ho perso niente! Solo un guanto." Gli versi un usucha bollente tra le mani rosse.\n\nIl tè sul bordo della tazza gela in un merletto. Lo guardi invece di berlo. Anche il freddo, qui, decora.`,cliff:`Sul vetro appannato, una scritta piccola: NEVE ANCHE DOMANI. Grafia di Yuki? O di Hana?`,choiceA:{label:'Riparate il tetto insieme a Ren',effect:'coraggio'},choiceB:{label:'Servite sotto il secchio-pino',effect:'dolcezza'},level:T(0,18,27,'awa',-1,'gelo'),letter:`Lettera 28 — Hana: "D'inverno il tè si beve in fretta e si ricorda piano."`,ps:{coraggio:"H. Avete riparato il tetto insieme, a due mani sul canale. Dentro, gocce: così si fa un tetto vero.",dolcezza:"H. Avete servito sotto il secchio col ramo di pino dentro. Yuki aveva ragione: era un'installazione firmata."},threads:['soma-junior']},
{id:32,chap:7,ep:2,kicker:'Cap.7-2 · Merletto',title:'Tè che gela',text:`Kiku attraversa il ponte nella neve con una coperta e una sfida: "Chi fa la schiuma che dura di più al freddo?" Il suo chashitsu ha la stufa nuova e te lo rinfaccia con amore.\n\nScopri che il gelo entra nel vassoio: tessere bloccate dal ghiaccio che non si spostano. Le sciogli col calore dei match vicini, come si scioglie tutto — con la vicinanza.\n\nMugi dorme dentro la coperta di Kiku. Traditore di velluto.`,cliff:`Kiku, andando via, lascia la coperta: "Tienila. Ho altre coperte. Ho sempre avuto tutto, tranne una nipote."`,choiceA:{label:'«Sei la nostra nonna d’inverno.»',effect:'dolcezza'},choiceB:{label:'Sfidi Kiku alla rivincita di primavera',effect:'coraggio'},level:T(2,18,27,'latte',-1,'gelo'),letter:`Coperta di Kiku — odora di cannella. Nessuna lettera, meglio: un peso caldo.`,ps:{dolcezza:"H. Quella sera l'hai chiamata la nonna d'inverno. Ha pianto un po', e non ha negato niente: era la risposta.",coraggio:"H. L'hai sfidata alla rivincita di primavera e hai vinto. Accetta la sconfitta come il freddo: a testa in giù."}},
{id:33,chap:7,ep:3,kicker:'Cap.7-3 · Tormenta',title:'Il giro bianco',text:`Tormenta. Nessun cliente. Solo tu, Ren, Mugi e Tè che dormono in una palla sola. Decidi di portare tè caldo ai senzatetto sotto il ponte — quello di Yuki.\n\nRiempi due thermos. Ren guida piano nella neve. Ogni tazza consegnata è un piccolo sole tascabile.\n\nTornando, trovi Sōma junior bloccato col motorino nella neve. Lo trainate, lo scaldate, lo sfamate. "Nonno dice che il giro non si interrompe mai. Nemmeno col bianco."`,cliff:`Junior ti consegna una lettera bagnata: è per Hana, scritta da Kiku quarant’anni fa. Mai spedita.`,choiceA:{label:'La consegni a Kiku di persona',effect:'coraggio'},choiceB:{label:'La leggi prima con Ren',effect:'dolcezza'},level:T(3,19,27,'respiro',-1,'gelo'),letter:`Lettera bagnata — Kiku a Hana, 1984: "Hai vinto tu. Ma che bella gara."`,ps:{coraggio:"H. L'hai consegnata a Kiku di persona, le mani gelate. Ha letto in silenzio, poi ha pianto dietro la porta.",dolcezza:"H. L'hai letta prima con Ren. Non volevi consegnarla da sola: leggerla insieme è già metà."},threads:['soma-junior']},
{id:34,chap:7,ep:4,kicker:'Cap.7-4 · Impronte',title:'Moka nella neve',text:`Impronte di gatto nella neve fresca, dal ponte fino alla tua porta. Moka, la tigrata di Kiku, ha attraversato il fiume gelato per venire a giudicare la tua schiuma invernale.\n\nLa fai sedere sul tavolo caldo. Annusa, assaggia il vapore, fa le fusa. Tè è gelosissimo e fa finta di dormire con un occhio aperto.\n\nYuki disegna le impronte: "Sembrano fiori bianchi che camminano."`,cliff:`Kiku telefona: "Tienila stanotte. Ha scelto lei. I gatti scelgono meglio delle persone."`,choiceA:{label:'Letto condiviso: due gatti, un chasen',effect:'dolcezza'},choiceB:{label:'Riporti Moka al ponte all’alba',effect:'coraggio'},level:T(1,19,27,'awa',-1,'gelo'),letter:`Impronta — Yuki te ne regala una ritagliata: "Portafortuna da neve."`,ps:{dolcezza:"H. Quella notte il letto è stato condiviso: due gatti, un chasen, un lato freddo. Nessuno perse il suo posto.",coraggio:"H. Hai riportato Moka al ponte all'alba. Si è girata e ti ha guardata come guarda chi torna. Poi è corsa via."},threads:['moka']},
{id:35,chap:7,ep:5,kicker:'Cap.7-5 · Disgelo',title:'Takeshi nella neve',text:`Takeshi arriva senza ombrello — nevica, e lui sorride: "La neve non bagna come la pioggia. Accarezza."\n\nChiede il koicha del ’64. Le tue mani lo sanno fare anche col freddo nelle ossa. Beve piano, guarda fuori.\n\n"Hana odiava l’inverno. Diceva che il tè doveva fare l’estate da solo." Ride, tossisce, ti stringe la mano: "Tu sei la sua estate."`,cliff:`Andando via, lascia sul tavolo un guanto solo. Il secondo, dice, "lo verrò a riprendere in primavera".`,choiceA:{label:'«Torni in primavera. Promesso.»',effect:'dolcezza'},choiceB:{label:'Gli cuci un guanto nuovo',effect:'coraggio'},level:T(5,20,28,'latte',-1,'gelo'),letter:`Guanto spaiato — lo appendi al muro. Promemoria di primavera.`,ps:{dolcezza:"H. Hai detto: torna in primavera. Ha appoggiato il guanto ed è uscito. Lui mantiene: verrà a prenderlo.",coraggio:"H. Gli hai cucito un guanto con la lana di Kiku. Non hai detto nulla: era un guanto, non una dichiarazione."}},
/* CAP 8 — Festival delle Lanterne */
{id:36,chap:8,ep:1,kicker:'Cap.8-1 · Lanterne',title:'Mercato di luce',text:`Febbraio. Festival delle Lanterne sul fiume: cento bancarelle, il tuo banchetto di tè al centro. Mika organizza la live dell’anno: "Stasera si fa la storia."\n\nDevi servire in fretta e con la schiuma ALTA — la gente giudica a occhio, tra le luci. Ogni tazza deve montare almeno al 55% o torna indietro.\n\nSōma junior fa il fattorino tra le bancarelle col motorino. Non perde niente. Ormai è un professionista.`,cliff:`Un critico anonimo con la maschera da volpe ordina "il peggiore che hai". Vuole metterti alla prova.`,choiceA:{label:'Gli servi il migliore, per ripicca dolce',effect:'dolcezza'},choiceB:{label:'«Toglimi la maschera prima.»',effect:'coraggio'},level:T(2,20,27,'latte',-1,null,55),letter:`Lanterina di carta — Yuki ci scrive sopra il tuo nome. Si accende da sola.`,ps:{dolcezza:"H. Gli hai servito il migliore, per ripicca dolce. Ha ringraziato uno sconosciuto: è il mestiere, e costa.",coraggio:"H. Gli hai detto: toglimi la maschera prima. Ha riso e l'ha tolta. Nessuno ti aveva mai chiesto una cosa così."},threads:['soma-junior']},
{id:37,chap:8,ep:2,kicker:'Cap.8-2 · Volpe',title:'Il critico mascherato',text:`La volpe si toglie la maschera: è Itsuki, tornato da Nara con una mostra fotografica sul mercato. "Volevo vedere se eri ancora la migliore. Lo sei."\n\nLe sue foto del festival sono piene di vapore e lanterne. In una ci sei tu, di spalle, che ridi. La intitola "Casa".\n\nRen finge gelosia per dieci secondi. Poi abbraccia il fratello così forte che quasi rompe una lanterna.`,cliff:`Itsuki propone: una mostra permanente nel magazzino sopra. "Il locale merita pareti che raccontano."`,choiceA:{label:'«Sì. Le tue pareti, le mie tazze.»',effect:'dolcezza'},choiceB:{label:'«Prima finiamo il festival.»',effect:'coraggio'},level:T(4,19,26,'respiro',4,'gelo',55),letter:`Foto "Casa" — te la regala. Sul retro: "A chi resta."`,ps:{dolcezza:"H. Gli hai detto: sì, le tue pareti e le mie tazze. Foto in alto, piatti in basso. Il tetto non perde più.",coraggio:"H. Hai detto: prima finiamo il festival. Le pareti aspettano, le lanterne no. E poi hanno aspettato benissimo."}},
{id:38,chap:8,ep:3,kicker:'Cap.8-3 · Miele',title:'Tè al miele nero',text:`Kiku presenta al festival il suo tè al miele nero e ti sfida pubblicamente: duello di dolcezza davanti a duecento persone. Moka, in prima fila su un cuscino, è il giudice supremo.\n\nIl vassoio è un campo di battaglia dolcissimo: boccioli che sbocciano e gelo delle notti di febbraio, tutto insieme. Servi col cuore in gola e le mani che ricordano.\n\nPareggio. La folla fischia e applaude. Moka fa le fusa a entrambe. Verdetto: due vincitrici.`,cliff:`Kiku ti sussurra: "L’anno prossimo, squadra unica. Hana-Kiku. Le faresti girare la testa dalla gioia."`,choiceA:{label:'«Squadra unica. Promesso.»',effect:'dolcezza'},choiceB:{label:'«Solo se Moka è capitana.»',effect:'coraggio'},level:T(0,20,27,'awa',-1,'mix',60),letter:`Nastro del festival — secondo posto ex aequo. Yuki lo mette al collo di Moka.`,ps:{dolcezza:"H. Hai detto: squadra unica, promesso. Kiku ha alzato il calice: tre minuti senza parlare di gare. Fine.",coraggio:"H. Hai detto: solo se Moka è capitana. Si è fatta nominare, ha preso il nastro. Kiku ha perso con onore."},threads:['moka']},
{id:39,chap:8,ep:4,kicker:'Cap.8-4 · Fiume',title:'Lanterne sull’acqua',text:`Chiusura del festival: cento lanterne sul fiume, ognuna con un desiderio. La tua dice "che nessuno abbia freddo". Ren, senza farsi vedere, ne accende una che dice "lei".\n\nServi l’ultimo giro a lume di lanterna. La schiuma deve essere perfetta — il 60% o niente. Le mani non tremano più. Non tremano da mesi, e te ne accorgi solo adesso.\n\nYuki lascia andare la sua lanterna: sopra c’è disegnata una tazza con dentro tutta la famiglia.`,cliff:`Una lanterna torna indietro con la corrente. Sopra c’è scritto, in grafia antica: "Grazie per il calore. H."`,choiceA:{label:'La tieni come reliquia',effect:'dolcezza'},choiceB:{label:'La rilanci più lontano',effect:'coraggio'},level:T(3,21,27,'respiro',-1,null,60),letter:`Lanterna tornata — la appendi al soffitto. Brucia ancora un poco, sempre.`,ps:{dolcezza:"H. Quella sera l'hai tenuta come una reliquia. La scritta ti guardava. Ha bruciato fino all'alba, per te.",coraggio:"H. Quella sera l'hai rilanciata lontano. L'hai rivista al dodicesimo: lontano non è perduto, è corrente."}},
{id:40,chap:8,ep:5,kicker:'Cap.8-5 · Cenere dolce',title:'Il chasen della madre',text:`Dopo il festival, Ren ti porta in disparte. Dalla borsa tira fuori un chasen antico, consumato: quello di SUA madre.\n\n"Lei non c’è più. Diceva che un chasen va dato a chi sa tenerlo senza stringere." Te lo mette in mano. Pesa come una promessa.\n\nNon è una proposta. È di più: è una radice che si offre. Piangi nel suo cappotto mentre le ultime lanterne si spengono.`,cliff:`Mugi annusa il chasen nuovo e lo approva con una testata. Adozione ufficiale.`,choiceA:{label:'«Lo terrò senza stringere.»',effect:'dolcezza'},choiceB:{label:'«Insegnerò a Yuki con questo.»',effect:'coraggio'},level:T(5,21,27,'latte',-1,'mix',65),letter:`Chasen della madre di Ren — secondo cuore del locale.`,ps:{dolcezza:"H. Quella sera hai detto: lo terrò senza stringere. La regola più difficile che ti hanno dato, capita metà.",coraggio:"H. Hai detto: insegnerò a Yuki con questo. Il chasen di sua madre in mani di bambina: prestito, non un dono."}},
/* CAP 9 — Ritorno al Vapore */
{id:41,chap:9,ep:1,kicker:'Cap.9-1 · Tempesta',title:'La notte che picchia',text:`Marzo. La tempesta di primavera picchia sul tetto riparato e vince lei: tegole in giardino, acqua nel magazzino, le foto di Itsuki in pericolo.\n\nTutto il quartiere accorre: Sōma e nipote, Kiku con le coperte, Mika coi follower diventati braccia, Rei e Yuki con gli asciugamani.\n\nSalvate tutto tranne una cosa: la tazza sbeccata del postino si rompe in due. Sōma la guarda e sorride strano.`,cliff:`"Era di mio padre," dice Sōma piano. "Forse è ora di bere da una tazza intera."`,choiceA:{label:'Gli regali la tazza di Hana',effect:'coraggio'},choiceB:{label:'Ricomponete la sbeccata col kintsugi',effect:'dolcezza'},level:T(1,21,27,'awa',-1,'gelo',65),letter:`Coccio d’oro — il kintsugi unisce più di prima.`,ps:{coraggio:"H. Gli hai regalato la tazza di Hana. Sōma ha capito e ha pianto: non per la tazza, per un debito restituito.",dolcezza:"H. Avete ricomposto la sbeccata col kintsugi. L'oro ha tenuto più della ceramica. Ora sta sul bancone."},threads:['soma-junior']},
{id:42,chap:9,ep:2,kicker:'Cap.9-2 · Fango',title:'Ricostruire',text:`Una settimana di fango, martelli e tè condiviso. Il locale diventa un cantiere-cooperativa: chi porta assi, chi porta riso, chi porta solo compagnia — che è il materiale più raro.\n\nI livelli si fanno duri: vassoi ghiacciati e boccioli selvatici insieme, clienti infreddoliti che vogliono tutto subito. Servi come non hai mai servito.\n\nLa sera crolli sul tatami. Ren ti massaggia le mani. "Queste mani hanno ricostruito una casa."`,cliff:`Sotto una tavola divelta trovate una scatola di latta: dentro, lettere di Hana mai lette. Dieci.`,choiceA:{label:'Le leggete una a sera, con calma',effect:'dolcezza'},choiceB:{label:'Le divori tutte stanotte',effect:'rabbia'},level:T(0,22,27,'latte',-1,'mix',70),letter:`Scatola di latta — dieci sere di Hana in arrivo.`,ps:{dolcezza:`Dieci sere, una per volta. È così che si legge una persona: piano, e con qualcuno seduto accanto.`,
        rabbia:`Dieci sere le hai prese tutte stanotte. Non ti giudico: anch'io ho fatto così con le tue.`},},
{id:43,chap:9,ep:3,kicker:'Cap.9-3 · Latta',title:'Dieci sere',text:`Ogni sera, una lettera della scatola. Hana giovane, Hana madre, Hana vecchia: consigli, ricette, scuse, risate. La decima è per te, col tuo nome sopra, grafia tremante.\n\n"Aoi, se leggi questa il tetto è caduto. Bene: i tetti cadono per far entrare il cielo. Ricostruisci più alto."\n\nPiangi dieci sere di fila. Al mattino servi meglio. Il dolore, frullato bene, diventa schiuma.`,cliff:`L’ultima lettera finisce così: "P.S. Sotto il pavimento, barattolo. Per le emergenze vere."`,choiceA:{label:'Apri il pavimento subito',effect:'coraggio'},choiceB:{label:'Aspetti l’emergenza vera',effect:'dolcezza'},level:T(4,21,26,'respiro',4,'gelo',70),letter:`Lettera 38 — "I tetti cadono per far entrare il cielo."`,ps:{coraggio:"H. Hai aperto il pavimento subito: sotto c'era il barattolo. Non era un'emergenza, era una promessa per te.",dolcezza:"H. Hai aspettato l'emergenza vera, e il barattolo era dove avevi detto. Non è pazienza: è fiducia nel posto."}},
{id:44,chap:9,ep:4,kicker:'Cap.9-4 · Barattolo',title:'L’emergenza vera',text:`L’emergenza vera arriva: Takeshi in ospedale, polmonite. Non grave, dice il medico, ma a ottant’anni ogni febbre è una montagna.\n\nApri il pavimento. Barattolo di latta: dentro, soldi piegati e un biglietto — "Per le emergenze vere. Come un amico malato. H."\n\nPaghi le cure, corri in ospedale col thermos. Takeshi beve e sorride: "Hana mi cura ancora. Testarda anche da morta."`,cliff:`Takeshi ti fa promettere: "Quando esco, voglio la festa. Con Moka giudice e tutto."`,choiceA:{label:'«Festa. Promesso. Con tutto.»',effect:'dolcezza'},choiceB:{label:'Resti con lui fino all’alba',effect:'coraggio'},level:T(2,23,28,'latte',-1,'mix',75),letter:`Biglietto del barattolo — "Per le emergenze vere."`,ps:{dolcezza:"H. Hai promesso la festa con tutto. Takeshi è guarito in nove giorni e ha contato i giorni, uno a uno.",coraggio:"H. Sei restata con lui fino all'alba: niente frulli, niente clienti. La notte più lunga che ho contato io."},threads:['moka']},
{id:45,chap:9,ep:5,kicker:'Cap.9-5 · Vapore',title:'Il voto del vapore',text:`Primavera vera. Il locale ricostruito è più alto, come ordinato: travi nuove, pareti di foto, angolo di Yuki, cesta di Moka, mensola per le 44 lettere.\n\nTakeshi esce dall’ospedale giusto per la festa. Tutto il quartiere beve. Il vapore sale dritto e alto, fino al tetto nuovo e oltre.\n\nPrendi il chasen della madre di Ren e fai un voto ad alta voce, davanti a tutti: mani che non tremano più, cuore che trema sempre.`,cliff:`Il vapore, per un secondo, disegna un volto. Hana. Che annuisce. Poi solo vapore.`,choiceA:{label:'«Resto. Ricostruisco. Sempre.»',effect:'dolcezza'},choiceB:{label:'«E se cadrà ancora, sarà più alto.»',effect:'coraggio'},level:T(3,24,28,'respiro',-1,'gelo',80),letter:`Lettera 44 — "Voto del vapore: restare è un verbo attivo. L’hai imparato."`,ps:{dolcezza:"H. Quella sera hai detto: resto, ricostruisco, sempre. Il vapore è salito dritto al tetto nuovo. Ho annuito.",coraggio:"H. Quella sera hai detto: se cadrà ancora, sarà più alto. L'unico voto che accetto: guardavi il cielo, non me."}},
];
const ORACLES = [
  { t: 'Usucha del Coraggio', x: 'Oggi frulla anche se tremi. La schiuma verrà lo stesso. Qualcuno noterà il tuo sforzo e resterà.' },
  { t: 'Koicha della Pazienza', x: 'Non rispondere subito al messaggio che ti ansia. Bevi prima qualcosa di denso. La risposta vera affiora sul fondo.' },
  { t: 'Sakura Imprevista', x: 'Un incontro dolce oggi: accettalo anche se sei in ritardo. Il rosa porta ritardo buono.' },
  { t: 'Yuzu che Sveglia', x: "Taglia una cosa acida dalla giornata: una lamentela, un dovere finto. Sentirai il petto più leggero." },
  { t: 'Kurogoma Ombra', x: 'La malinconia di oggi è solo stanchezza travestita. Dormi 20 minuti in più. Il nero schiarirà.' },
  { t: 'Mochi Bianco', x: 'Offri qualcosa gratis oggi: un sorriso, un tè, tempo. Tornerà centuplicato entro tre piogge.' },
  { t: 'Tazza Arcobaleno', x: 'Osserva i piccoli match della giornata: due piccioni, due semafori verdi. Sei in combo. Continua.' },
  { t: 'Miao-cha del Gatto', x: 'Oggi dormi 20 minuti dove capita, come Tè sulle tazze calde. Il riposo improvvisato è il più sacro.' },
  { t: 'Hana Ventenne', x: 'Fai una cosa che la te ventenne amava e la te adulta rimanda. Il chasen ricorda le mani giovani.' },
];
const ENDINGS = {
  'finale-resta': { title: 'Finale: RESTO 🌿', text: `Firmi. La sala tatami sopra apre in primavera. Ren resta come compagno e lavapiatti ufficiale. Yuki ha un angolo tutto suo per disegnare.\n\nTakeshi viene ogni pioggia. Un giorno non viene più: sul suo tavolo trovi l'ombrello nero piegato e un biglietto: "Grazie per l'infinito."\n\nIl chashitsu Hana non chiude mai più. Perché hai capito il segreto: restare è un verbo attivo.` },
  'finale-radici': { title: 'Finale: RADICI E ALI 🌳', text: `Firmi i 10 anni E compri un furgoncino verde: d'inverno sala tatami a Kyoto, d'estate "Hana on the road" per il Giappone.\n\nSōma viaggia con voi una settimana l'anno. Kiku custodisce il locale quando siete via. Itsuki fotografa ogni tappa. Tè dorme sul cruscotto, Mugi sul cambio.\n\nYuki, ormai grande, disegna la mappa del viaggio sulla parete: 47 prefecture, 47 tazze. Takeshi vi aspetta a ogni ritorno con l'ombrello di carta.\n\nRadici per restare, ali per tornare. Hai preso tutto.` },
  'finale-radici-sola': { title: 'Finale: RADICI E ALI (da sola) 🕊️🌳', text: `Prima di firmare, parti da sola un mese: solo zaino, chasen e il quaderno di Yuki.\n\nTorni con 30 pagine di appunti e una certezza: il locale è casa, il mondo è giardino. Firmi, apri la sala tatami, e ogni autunno viaggi da sola a imparare un tè nuovo.\n\nRen ti aspetta al binario ogni volta. "Bentornata" è la frase più romantica che conosce.` },
  'finale-lascia': { title: 'Finale: LASCIO ANDARE 🕊️', text: `Vendi. Piangi una settimana. Poi parti con Ren e un chasen in valigia: apri un banchetto itinerante, "Hana on the road".\n\nA Kyoto resta una targa: "Qui si imparava a restare, ora si impara ad andare."\n\nYuki ti scrive ogni mese un disegno di tazza da una città diversa. Takeshi ti segue col pensiero come pioggia buona.\n\nLasciare andare, scopri, è un altro modo di servire.` },
  'matcha-eterno': { title: 'Finale segreto: MATCHA ETERNO ✨', text: `60 stelle. Tutte le lettere. Tutti i riti perfetti.\n\nQuella notte Hana ti appare in sogno giovane, mano nella mano con Takeshi giovane: "Hai fatto il miracolo: hai tenuto insieme tutti senza trattenere nessuno."\n\nTi svegli col chasen caldo. Fuori nevica sakura fuori stagione.\n\nIl locale diventa leggenda: chi beve lì, perdona qualcuno entro tre giorni. Compreso te stessa.` },
};
window.MHStory = { CHAPTERS, CHARACTERS, STORY, ORACLES, ENDINGS };
})();
